package rules

import (
	"strings"
	"testing"

	"github.com/adams-shaun/gorge/testkit/testutil"
)

// Farm finding SUP `stack` (SUP-s127-supp xe:RAND:0:10:w15 and siblings):
// gorge showed [ability:Exhaustion@p0] on the stack at p1's next upkeep where
// Forge and XMage showed []. Exhaustion's self-exile body is Static$ True: the
// Effect's "during their next untap step" duration is continuous-effect
// bookkeeping (CR 611.2a "A continuous effect generated by the resolution of a
// spell or ability lasts as long as stated by the spell or ability creating
// it"), not a delayed triggered ability that uses the stack (CR 603.7).
func TestFarmExhaustion(t *testing.T) {
	t.Parallel()
	reg := testutil.CorpusRegistry(t)
	steps := []string{
		`{"op":"activate","seat":0,"card":"p0:Island","ability_index":0}`,
		`{"op":"activate","seat":0,"card":"p0:Island#2","ability_index":0}`,
		`{"op":"activate","seat":0,"card":"p0:Island#3","ability_index":0}`,
		`{"op":"cast","seat":0,"card":"p0:Exhaustion","targets":["p1"]}`,
	}
	for range 8 {
		steps = append(steps, `{"op":"pass","seat":0}`, `{"op":"pass","seat":1}`)
	}
	sc := `{"name":"farm-exhaustion-static-self-exile","cr":["611.2a","603.7"],"setup":{` +
		`"p0":{"battlefield":["Island","Island","Island"],"hand":["Exhaustion"]},` +
		`"p1":{"battlefield":["Grizzly Bears","Forest"]}},"steps":[` + strings.Join(steps, ",") + `]}`
	res, err := RunOracleScenarioJSON(reg, []byte(sc))
	if err != nil {
		t.Fatalf("scenario JSON: %v", err)
	}
	found := false
	for _, s := range res.Snapshots {
		if s.Active != 1 || s.Step != "upkeep" {
			continue
		}
		found = true
		var stack []string
		for _, it := range s.Stack {
			stack = append(stack, it.Kind+":"+it.Source)
		}
		if len(stack) != 0 {
			t.Fatalf("stack at p1's upkeep = %v, want []", stack)
		}
	}
	if !found {
		var seen []string
		for _, s := range res.Snapshots {
			seen = append(seen, s.Step)
		}
		t.Fatalf("precondition: no snapshot at p1's upkeep (fails %v; steps %v)", res.Fails, seen)
	}
}
